"""Freshness of a stored HTTP response, an RFC 9111 subset. See task.md."""

from __future__ import annotations

from dataclasses import dataclass
import re
import calendar
from datetime import datetime

FRESH = "FRESH"
STALE = "STALE"
MUST_REVALIDATE = "MUST_REVALIDATE"

MONTH_MAP = {
    "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
    "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12,
}

DAY_NAMES = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}


class HeaderError(ValueError):
    """Raised for a header that is not a well-formed HTTP-date."""


@dataclass(frozen=True)
class Result:
    verdict: str
    current_age: int
    freshness_lifetime: int


def _parse_imf_fixdate(date_str: str) -> int:
    """Parse IMF-fixdate and return epoch seconds. Raises HeaderError if invalid."""
    date_str = date_str.strip()

    if len(date_str) != 29:
        raise HeaderError(f"Invalid date format: {date_str}")

    day_name = date_str[0:3]
    if day_name not in DAY_NAMES:
        raise HeaderError(f"Invalid day name: {day_name}")

    if date_str[3:5] != ", ":
        raise HeaderError(f"Invalid date format after day name")

    day_str = date_str[5:7]
    if not day_str.isdigit():
        raise HeaderError(f"Invalid day of month: {day_str}")
    day = int(day_str)

    if date_str[7] != " ":
        raise HeaderError(f"Invalid date format")

    month_str = date_str[8:11]
    if month_str not in MONTH_MAP:
        raise HeaderError(f"Invalid month: {month_str}")
    month = MONTH_MAP[month_str]

    if date_str[11] != " ":
        raise HeaderError(f"Invalid date format")

    year_str = date_str[12:16]
    if not year_str.isdigit():
        raise HeaderError(f"Invalid year: {year_str}")
    year = int(year_str)

    if date_str[16] != " ":
        raise HeaderError(f"Invalid date format")

    time_str = date_str[17:25]
    if date_str[25:29] != " GMT":
        raise HeaderError(f"Invalid date format: missing GMT")

    hms = time_str.split(":")
    if len(hms) != 3:
        raise HeaderError(f"Invalid time format")

    hour_str, minute_str, second_str = hms
    if not hour_str.isdigit() or not minute_str.isdigit() or not second_str.isdigit():
        raise HeaderError(f"Invalid time format")

    hour = int(hour_str)
    minute = int(minute_str)
    second = int(second_str)

    try:
        dt = datetime(year, month, day, hour, minute, second)
        return calendar.timegm(dt.timetuple())
    except ValueError as e:
        raise HeaderError(f"Invalid date/time: {e}")


def _get_header(headers: dict[str, str], name: str) -> str | None:
    """Get a header value case-insensitively."""
    for key, value in headers.items():
        if key.lower() == name.lower():
            return value
    return None


def _parse_cache_control(header_value: str) -> dict[str, str | None]:
    """Parse Cache-Control header into directives. Returns dict of name -> value (None if no value)."""
    directives = {}

    # Split by comma but respect quoted values
    current = ""
    in_quotes = False

    for char in header_value:
        if char == '"':
            in_quotes = not in_quotes
            current += char
        elif char == "," and not in_quotes:
            directive = current.strip()
            if directive:
                _parse_directive(directive, directives)
            current = ""
        else:
            current += char

    if current.strip():
        directive = current.strip()
        _parse_directive(directive, directives)

    return directives


def _parse_directive(directive: str, directives: dict[str, str | None]) -> None:
    """Parse a single directive and update directives dict."""
    if "=" not in directive:
        name = directive.strip()
        directives[name.lower()] = None
        return

    parts = directive.split("=", 1)
    name = parts[0].strip()
    value = parts[1].strip()

    if value.startswith('"') and value.endswith('"'):
        value = value[1:-1]

    directives[name.lower()] = value


def _get_directive_value(directives: dict[str, str | None], name: str) -> int | None:
    """Get numeric directive value, or None if absent/malformed."""
    value = directives.get(name.lower())
    if value is None:
        return None
    if not value.isdigit():
        return None
    return int(value)


def evaluate(
    response_headers: dict[str, str],
    request_headers: dict[str, str],
    request_time: int,
    response_time: int,
    now: int,
) -> Result:
    """Decide whether the stored response may be reused at `now`."""

    response_cache_control = _parse_cache_control(_get_header(response_headers, "Cache-Control") or "")
    request_cache_control = _parse_cache_control(_get_header(request_headers, "Cache-Control") or "")

    date_str = _get_header(response_headers, "Date")
    if date_str:
        date_value = _parse_imf_fixdate(date_str)
    else:
        date_value = response_time

    age_value = _get_directive_value(response_cache_control, "Age")
    if age_value is None:
        age_value = 0

    age_str = _get_header(response_headers, "Age")
    if age_str and age_str.isdigit():
        age_value = int(age_str)

    response_delay = response_time - request_time
    apparent_age = max(0, response_time - date_value)
    corrected_age = age_value + response_delay
    initial_age = max(apparent_age, corrected_age)
    resident_time = now - response_time
    current_age = initial_age + resident_time

    freshness_lifetime = _calculate_freshness_lifetime(response_headers, response_cache_control, date_value)

    request_max_age = _get_directive_value(request_cache_control, "max-age")
    if request_max_age is not None:
        freshness_lifetime = min(freshness_lifetime, request_max_age)

    verdict = _determine_verdict(
        response_cache_control, request_cache_control, current_age, freshness_lifetime
    )

    return Result(verdict, current_age, freshness_lifetime)


def _calculate_freshness_lifetime(
    response_headers: dict[str, str],
    response_cache_control: dict[str, str | None],
    date_value: int,
) -> int:
    """Calculate freshness lifetime according to RFC 9111."""

    s_maxage = _get_directive_value(response_cache_control, "s-maxage")
    if s_maxage is not None:
        return s_maxage

    max_age = _get_directive_value(response_cache_control, "max-age")
    if max_age is not None:
        return max_age

    expires_str = _get_header(response_headers, "Expires")
    if expires_str:
        expires_value = _parse_imf_fixdate(expires_str)
        lifetime = expires_value - date_value
        return max(0, lifetime)

    last_modified_str = _get_header(response_headers, "Last-Modified")
    if last_modified_str:
        last_modified_value = _parse_imf_fixdate(last_modified_str)
        lifetime = (date_value - last_modified_value) // 10
        return max(0, lifetime)

    return 0


def _determine_verdict(
    response_cache_control: dict[str, str | None],
    request_cache_control: dict[str, str | None],
    current_age: int,
    freshness_lifetime: int,
) -> str:
    """Determine verdict based on RFC 9111 rules."""

    if ("no-store" in response_cache_control or
        "no-cache" in response_cache_control or
        "must-revalidate" in response_cache_control or
        "no-cache" in request_cache_control):
        return MUST_REVALIDATE

    min_fresh_str = request_cache_control.get("min-fresh")
    min_fresh = 0
    if min_fresh_str is not None and min_fresh_str.isdigit():
        min_fresh = int(min_fresh_str)

    if freshness_lifetime > current_age + min_fresh:
        return FRESH

    if "max-stale" in request_cache_control:
        max_stale_str = request_cache_control["max-stale"]
        if max_stale_str is None:
            return FRESH
        if max_stale_str.isdigit():
            max_stale = int(max_stale_str)
            if current_age - freshness_lifetime <= max_stale:
                return FRESH

    return STALE
